// Accepts JSON posted by the cloud routine: { subject, html, body, slot, postDateTime, deadline }
// If 'html' is supplied, use it as-is. Otherwise wrap the plain-text 'body' in the NG branded shell.
const inp = $input.first().json.body ? $input.first().json.body : $input.first().json;
const subject = inp.subject || 'NG IG — 24h Pre-Post Brief';
const slot = inp.slot || '';
const postDateTime = inp.postDateTime || '';
const deadline = inp.deadline || '';
let html = inp.html;
if (!html) {
  const safe = (inp.body || '').replace(/\n/g, '<br>');
  html = `<!DOCTYPE html><html><body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;background:#f5f5f5;margin:0;padding:20px;">
  <div style="max-width:640px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);">
    <div style="background:#102442;padding:24px 28px;">
      <h1 style="color:#fff;margin:0;font-size:19px;font-weight:700;">NG Instagram — 24h Pre-Post Brief</h1>
      <p style="color:#7eb3d4;margin:4px 0 0;font-size:13px;">${slot}${postDateTime ? ' · posts ' + postDateTime : ''}</p>
    </div>
    <div style="padding:24px 28px;color:#1a1a1a;font-size:14px;line-height:1.6;">${safe}</div>
    <div style="background:#f8fafc;padding:14px 28px;text-align:center;">
      <p style="color:#999;font-size:11px;margin:0;">Auto-brief by the NG instagram-content agent · Chief-of-Staff audited · decision needed by ${deadline || 'the stated deadline'}</p>
    </div>
  </div></body></html>`;
}
return [{ json: { subject, html } }];
